/* C interface to the official CEC2017 code for bioqpso/benchmarks/cec2017_official.py.
   The official prototype and globals come from a header that the fetch script extracts from the
   official main.cpp; this file defines only the data directory and two exported functions. */
#include <string.h>
#include "cec17_official_decls.h"  /* generated by scripts/fetch_cec2017_official.sh */

char cec17_dir[1024] = "input_data";

extern "C" {

void cec17_set_dir(const char *dir) {
    strncpy(cec17_dir, dir, sizeof(cec17_dir) - 1);
    cec17_dir[sizeof(cec17_dir) - 1] = '\0';
    ini_flag = 0;  /* reload data on the next call */
}

/* x: mx points of dimension nx, row-major; f: mx values. */
void cec17_eval(double *x, double *f, int nx, int mx, int func_num) {
    cec17_test_func(x, f, nx, mx, func_num);
}

}
